def check_D_k4(x1, x2, x3, x4):
    # Pairs (m, n) and corresponding coefficients C = m+n
    pairs = [
        (1, 2, 3),
        (1, 3, 4),
        (1, 4, 5),
        (2, 3, 5),
        (2, 4, 6),
        (3, 4, 7)
    ]

    D_values = []

    # (m, n, C)
    for m, n, C in pairs:
        xn_sq = xn**2
        xm_sq = xm**2

        if n == 2 and m == 1:
            val = abs(x2**2 - x1**2)
        elif n == 3 and m == 1:
            val = abs(x3**2 - x1**2)
        elif n == 4 and m == 1:
            val = abs(x4**2 - x1**2)
        elif n == 3 and m == 2:
            val = abs(x3**2 - x2**2)
        elif n == 4 and m == 2:
            val = abs(x4**2 - x2**2)
        elif n == 4 and m == 3:
            val = abs(x4**2 - x3**2)
        else:
            # Should not happen with fixed indexing logic above
            continue

        D_values.append(C * val)

    return min(D_values)

